import { getMinMax } from "./getMinMax";
export const getRange = (data) => {
    const { min, max } = getMinMax(data);
    let range = max - min;
    if (range === 0) {
        range = min * 0.1;
    }
    const suggestedMin = min - range * 0.1;
    const suggestedMax = max + range * 0.1;
    return {
        min: suggestedMin,
        max: suggestedMax
    };
};
